"""
Server Executor (RemoteExecutor)
""" 
import Pyro5.api 
import sys
import types

# Helper class for module import
class LocalModuleImporter:  
    def __init__(self, module_dict):  
        """  
        Initialize the custom importer with a dictionary of modules.  
        :param module_dict: A dictionary where keys are module names (e.g., "my_data.test_data")  
                            and values are module code or objects.  
        """  
        self.module_dict = module_dict  

    def find_spec(self, fullname, path, target=None):  
        """  
        Check if the requested module is in the module_dict.  
        :param fullname: The full name of the module being imported (e.g., "my_data.test_data").  
        :return: A module spec if the module is found, otherwise None.  
        """  
        if fullname in self.module_dict:  
            return self  # Return self as the loader  
        return None  

    def create_module(self, spec):  
        """  
        Create a new module object.  
        :param spec: The module spec.  
        :return: A new module object.  
        """  
        return None  # Use the default module creation mechanism  

    def exec_module(self, module):  
        """  
        Execute the module code.  
        :param module: The module object to execute.  
        """
        if module.__name__ in self.module_dict:  
            # Execute the module code in the module's namespace  
            exec(self.module_dict[module.__name__], module.__dict__)  
        else:  
            raise ModuleNotFoundError(f"Module '{module.__name__  }' not found in module_dict.")  

    def load_module(self, fullname):  
        """  
        Load a module, handling dotted names (e.g., "my_data.test_data").  
        :param fullname: The full name of the module to load.  
        """  
        if fullname in sys.modules:  
            return sys.modules[fullname]  # Return the already-loaded module  

        # Create parent packages dynamically for dotted module names  
        parts = fullname.split(".")  
        for i in range(1, len(parts)):  
            package_name = ".".join(parts[:i])  
            if package_name not in sys.modules:  
                # Create a new package  
                package = types.ModuleType(package_name)  
                package.__path__ = []  # Mark it as a package  
                sys.modules[package_name] = package  

        # Create the module  
        module = types.ModuleType(fullname)  
        sys.modules[fullname] = module  

        # Execute the module code  
        if fullname in self.module_dict:  
            exec(self.module_dict[fullname], module.__dict__)  
        else:  
            raise ModuleNotFoundError(f"Module '{fullname}' not found in module_dict.")  

        return module  


@Pyro5.api.expose  
class RemoteExecutor:  
    def __init__(self, daemon): 
        self.modules = sys.modules
        self.exec_globals = globals().copy() # Store the global namespace for dynamic code execution
        self.daemon = daemon
        self.restart_triggered = False  # Tracks if a restart should occur

    def execute(self, code):  
        """  
        Execute the given Python code string in the remote environment.  
        """  
        try: 
            if isinstance(code, dict):
                # Create a new module object
                for module_name, module_code in code.items():
                    self.create_module(module_name, module_code)
            elif isinstance(code, list):
                for src in code:
                    exec(src, self.exec_globals)
            else:
                exec(code, self.exec_globals)
            return {"status": "success"}  
        except Exception as e:  
            return {"error": str(e)}

    def create_module(self, full_module_path, source_code):
        """  
        Dynamically create a module with a complex path (e.g., 'package_name.subpackage_name.module_name').  
        
        :param full_module_path: The full dotted path of the module (e.g., 'package_name.subpackage_name.module_name').  
        :param source_code: The source code to execute in the module's namespace.  
        :return: The created module.  
        """  
        # Split the full module path into parts (e.g., ['package_name', 'subpackage_name', 'module_name'])  
        parts = full_module_path.split('.')  
        
        # Step 1: Create or retrieve the parent packages  
        current_package = None  
        current_path = ""  
        for part in parts[:-1]:  # Iterate over all parts except the last one (the module name)  
            current_path = f"{current_path}.{part}" if current_path else part  
            
            # Check if the package already exists in sys.modules  
            if current_path in self.modules:  
                current_package = self.modules[current_path]
            else:  
                # Create a new package  
                current_package = types.ModuleType(current_path)  
                self.modules[current_path] = current_package  
                
                # Link the package to its parent (if it exists)  
                if '.' in current_path:  
                    parent_path = current_path.rsplit('.', 1)[0]  
                    parent_package = self.modules[parent_path]  
                    setattr(parent_package, part, current_package)  

        # Step 2: Create the final module  
        module_name = parts[-1]  
        full_module_name = full_module_path  
        module = types.ModuleType(full_module_name)  
        self.modules[full_module_name] = module  

        # Populate the module with the provided source code  
        exec(source_code, module.__dict__)  

        # Step 3: Link the module to its parent package  
        if current_package is not None:  
            setattr(current_package, module_name, module)  
        print(f"Create module {full_module_path}")
        return module

    def setup_modules(self, module_dict: dict):  
        """  
        Initialize the ModuleManager by dynamically importing the specified modules.  

        :param module_dict: dict of modules to import (e.g., {"math_operations": code_str1:, "string_operations":code_str2})  
        """
        sys.meta_path.insert(0, LocalModuleImporter(module_dict)) 
        for module_name, module_source in module_dict.items():
            try:  
                self.create_module(module_name, module_source)
            except ModuleNotFoundError:  
                print(f"Warning: Module '{module_name}' not found and will be skipped.")  
            except ImportError as e:
                print(f"Error importing module '{module_name}': {e}")

    def run_function(self, func_name, *args, **kwargs):  
        """  
        Dynamically call a function by its name. If the name is basic (e.g., 'add'),  
        search for it across all available modules.  

        :param func_name: The name of the function (e.g., 'add' or 'package_name.module_name.add').  
        :param args: Positional arguments to pass to the function.  
        :param kwargs: Keyword arguments to pass to the function.  
        :return: The result of the function call.  
        """  
        # If the function name contains a dot, treat it as a fully qualified name  
        if '.' in func_name:  
            module_path, function_name = func_name.split('.')  
            module_name = '.'.join(module_path)  

            # Check if the module exists in sys.modules  
            if module_name not in self.modules:  
                raise ImportError(f"Module '{module_name}' not found.")  

            # Retrieve the module from sys.modules  
            module = self.modules[module_name]  

            # Check if the function exists in the module  
            if not hasattr(module, function_name):  
                raise AttributeError(f"Function '{function_name}' not found in module '{module_name}'.")  

            # Retrieve the function  
            func = getattr(module, function_name)  

            # Check if the retrieved object is callable  
            if not callable(func):  
                raise TypeError(f"'{function_name}' in module '{module_name}' is not callable.")  

            # Call the function with the provided arguments and return the result  
            return func(*args, **kwargs)  

        # If the function name is basic, search for it across all modules  
        else:  
            for module_name, module in self.modules.items():  
                # Skip irrelevant modules (e.g., built-in modules)  
                if not isinstance(module, types.ModuleType):  
                    continue  

                # Check if the function exists in the module  
                if hasattr(module, func_name):  
                    func = getattr(module, func_name)  

                    # Check if the retrieved object is callable  
                    if callable(func):  
                        # Call the function with the provided arguments and return the result  
                        return func(*args, **kwargs)  

            # If the function is not found in any module, raise an error  
            raise NameError(f"Function '{func_name}' not found in any loaded module.")  
       
    def get_variable(self, var_name):  
        """  
        Retrieve a variable from the global namespace.  
        :param var_name: The name of the variable to retrieve.  
        :return: The value of the variable, or None if it doesn't exist.  
        """  
        return self.exec_globals.get(var_name, None)

    def reset(self):
        """
        Trigger a restart by set restart_triggered to True
        """
        self.restart_triggered = True

    def shutdown(self):  
        print("Shutdown request received. Shutting down the daemon...")  
        self.daemon.shutdown()  # Shutdown the daemon  
        return "Server is shutting down."  

# Start the Pyro5 server  
def start_server():
    try:
        with Pyro5.api.Daemon(host="0.0.0.0", port=9090) as daemon: 
            # Register the RemoteExecutor object with a unique name  
            executor = RemoteExecutor(daemon)   
            uri = daemon.register(executor,  objectId="RemoteExecutor")  
            print(f"RemoteExecutor is running. URI: {uri}")
            try:
                daemon.requestLoop(loopCondition=lambda: not executor.restart_triggered)  
            except KeyboardInterrupt:  
                print("KeyboardInterrupt received.")
            finally: 
                print("Cleaning up and shutting down the daemon...")  
                daemon.shutdown() 
            return "restart_triggered" 
    except Exception as e:
        print(f"An error occurred: {e}") 
        return "exception_occurred"

if __name__ == "__main__":  
    while True:  
        result = start_server()  
        if result == "restart_triggered":  
            print("Restart server...")  
            continue  # Restart the process loop  
        else:  
            break   